  when question_text ~* '(?i)master budget|cash budget|sales budget|production budget|materials budget|purchases budget|direct labor budget|budgeted production|budgeted sales|budgeted direct labor|pro forma|zero-based|bottom-up|top-down|participatory|rolling budget|cash disbursement|cash collection|budgeted cost|budgeted at|desired ending inventory|units to be produced' then 'Section B'
