  when question_text ~* '(?i)variance|transfer pric|balanced scorecard|residual income|return on investment|\mroi\M|responsibility account|responsibility center|cost center|profit center|investment center|standard cost|flexible budget|segment margin|economic value added|\meva\M|performance measure|performance measurement|performance report|break-even|breakeven|break even|margin of safety|contribution margin|operating leverage|sales mix|key performance indicator|\mkpi|cost of capital|hurdle rate|benchmark|decentraliz|controllable|divisional|segment reporting|division manager|segment manager|residual earnings|contribution approach|segment profitability|responsibility reporting|performance evaluation|pricing strateg|skimming|penetration pricing|\mleverage|cost of debt|breake\s*v?\s*en|unit sales' then 'Section C'
  when question_text ~* '(?i)activity-based|\mabc\M|process cost|job order|job costing|equivalent unit|joint product|split-off|by-product|byproduct|spoilage|\mrework|\mscrap|high-low|theory of constraints|target cost|kaizen|life-cycle|absorption costing|variable costing|direct costing|throughput cost|backflush|overhead rate|overhead application|predetermined overhead|cost driver|cost pool|cost allocation|service department|reciprocal method|step-down method|underapplied|overapplied|prime cost|conversion cost|cost of goods manufactured|cost behavior|relevant cost|make-or-buy|opportunity cost|sunk cost|avoidable|differential cost|special order|process further|normal costing|actual costing|manufacturing overhead|factory overhead|cost estimation|curvilinear|step cost|semivariable|mixed cost|departmental rate|plant-wide|machine-hour|labor-hour|fifo method|weighted-average method|batch-level|product-sustaining|unit-level|facility-level|cost hierarchy|setup cost|cost object|cost assignment|indirect material|cost accountant|cost accounting|process manufacturing|continuous flow|conversion cost per|equivalent production|transferred-in|transferred in|normal loss|abnormal loss|yield loss|work-in-process|joint cost|value chain|just-in-time|\mjit|outsourc|core competency|life cycle|product life|\mvariable cost|\mfixed cost|period cost|\mproduct cost|cost classification|classification and behavior|traditional cost system|establishing a cost system|cost system|inventoriable|not relevant to a future decision|incurred in the past|target price|target return|desired rate of return|selling price per|cost-plus|markup|direct labor hour|split - off|additional direct labor hour|production tooling|recover the costs' then 'Section D'
  when question_text ~* '(?i)\mbudget|forecast|learning curve|regression|exponential smoothing|time series|moving average|\mdelphi\M|budgetary slack|sensitivity analysis|scenario|\mswot|planning horizon|sales forecast|capital expenditure budget|budget committee|budget director|profit plan|annual planning|operating budget|financial budget|vision statement|mission statement|strategic management|strategy level|competitive strategy|focus strategy|cost leadership|differentiation strategy|environmental scanning|internal capability|tactical goal|tactical objective|long-term goal|expected monetary value|expected value|probability distribution|decision tree|decision making under|conditions of uncertainty|payoff table|perfect information|external analysis|industry analysis|sustainable competitive|business process improvement|continuous improvement|\mreengineering|net present value|\mnpv|internal rate of return|\mirr|payback|discounted cash flow|capital budgeting|capital investment|capital project|\mannuity|market share|market analysis|yield curve|perfect competition|price elasticity|\melasticity|demand curve|supply curve|\mmarginal revenue|microeconom|\moligopol|monopol|economic profit|law of diminishing|credit terms|payment terms|cash discount|forgo|net 30|compensating balance|lockbox|speculative motive|transaction motive|precautionary motive|working capital|money market|commercial paper|mutually exclusive|investment project|present value of the cash|operating cycle|cash cycle|current asset|credit policy|credit applicant|average collection|collection period|credit standards|credit scoring|explicit cost|implicit cost|vertical integration|treasurer|spin\s*-?\s*off' then 'Section B'
  when question_text ~* '(?i)revenue recognition|\mifrs\M|\mgaap\M|fair value|equity method|treasury stock|impairment|goodwill|dividend|earnings per share|diluted|\mbond|statement of cash flows|operating activities|investing activities|financing activities|indirect method|amortization|intangible|\mpatent|copyright|trademark|franchise|depletion|sum-of-the-years|double-declining|\mlifo|\mfifo|lower of cost|net realizable|allowance for doubtful|bad debt|held-to-maturity|available-for-sale|trading securities|debt securities|amortized cost|consolidat|business combination|noncontrolling|deferred tax|income tax|effective tax rate|current ratio|quick ratio|acid-test|common-size|gross margin|\mnet income|restatement|discontinued operation|prior period adjustment|\maccrue|accrued|prepaid|unearned|contingent|warranty|\mpension|research and development|capital expenditure|revenue expenditure|book value|carrying value|salvage value|residual value|straight-line|\mlease|\minventory|raw material|finished goods|cost of goods sold|gross profit|operating income|pretax income|interest capitalization|materiality|going concern|full disclosure|consistency principle|monetary unit|historical cost|matching principle|revenue principle|expense recognition|accounts payable|notes payable|long-term debt|mortgage|installment|percentage of completion|completed contract|consignment|bill-and-hold|barter|nonmonetary|exchange lacks|constructive obligation|probable and estimable|annual report|interim report|quarterly report|earnings quality|off-balance sheet|variable interest entity|special purpose entity|push-down|purchase method|pooling|integrated report|value creation|six capitals|sustainab|social responsibility|stock split|\mpar value|shareholders.? equity|statement of shareholders|performance obligation|cash equivalent|write-off|current liability|long-term liability|common stock|preferred stock|paid-in capital|share premium|retained earnings|stock dividend|voting interest|significant influence|equity securities|share-based|declaration date|record date|payment date|other comprehensive income|remeasurement|quality of earnings|receivable turnover|debt to equity|debt-to-equity|times interest earned|return on assets|return on equity|return on sales|profit margin|asset turnover|\mturnover|capital structure|debt ratio|exchange rate|foreign currency|forward rate|spot rate|forward market|acid\s*-\s*test|financial statement analysis|base-year|base year|marketable|times earnings|value per share|monetary system|commercial draft|\mgold\b|\maccount payable|dupont|du pont|balance in accounts receivable|cash ratio|current liabilities|will (increase|decrease)' then 'Section A'
end, updated_at = now()
where is_active and part='Part 1' and (section is null or section='');